    ON review_replies;

DROP POLICY IF EXISTS "Vendors update their own reply"
    ON review_replies;

DROP POLICY IF EXISTS "Vendors delete their own reply"
    ON review_replies;

DROP POLICY IF EXISTS "Admins have full access to review replies"
    ON review_replies;


-- =============================================================================
-- SECTION 12: RLS POLICIES -- reviews
-- =============================================================================

DROP POLICY IF EXISTS "Students and vendors see visible reviews" ON reviews;
CREATE POLICY "Students and vendors see visible reviews" ON reviews
FOR SELECT
USING (
    is_visible = true
    OR is_admin()
);


DROP POLICY IF EXISTS "Students insert their own reviews" ON reviews;
CREATE POLICY "Students insert their own reviews" ON reviews
FOR INSERT
WITH CHECK (
    auth.uid() = student_id
    AND is_student()
);


DROP POLICY IF EXISTS "Students update their own reviews" ON reviews;
CREATE POLICY "Students update their own reviews" ON reviews
FOR UPDATE
USING (
    auth.uid() = student_id
    AND is_student()
)
WITH CHECK (
    auth.uid() = student_id
    AND is_student()
);


DROP POLICY IF EXISTS "Students delete their own reviews" ON reviews;
CREATE POLICY "Students delete their own reviews" ON reviews
FOR DELETE
USING (
    auth.uid() = student_id
    AND is_student()
);


DROP POLICY IF EXISTS "Admins have full access to reviews" ON reviews;
CREATE POLICY "Admins have full access to reviews" ON reviews
FOR ALL
USING (
    is_admin()
)
WITH CHECK (
    is_admin()
);


-- =============================================================================
-- SECTION 13: RLS POLICIES -- review_replies
-- =============================================================================

DROP POLICY IF EXISTS "Anyone can see review replies" ON review_replies;
CREATE POLICY "Anyone can see review replies" ON review_replies
FOR SELECT
USING (
    EXISTS (
        SELECT 1
        FROM reviews r
        WHERE r.id = review_replies.review_id
          AND (
              r.is_visible = true
              OR is_admin()
          )
    )
);


DROP POLICY IF EXISTS "Vendors insert their own reply" ON review_replies;
CREATE POLICY "Vendors insert their own reply" ON review_replies
FOR INSERT
WITH CHECK (
    auth.uid() = vendor_id
    AND is_vendor()
);


DROP POLICY IF EXISTS "Vendors update their own reply" ON review_replies;
CREATE POLICY "Vendors update their own reply" ON review_replies
FOR UPDATE
USING (
    auth.uid() = vendor_id
    AND is_vendor()
)
WITH CHECK (
    auth.uid() = vendor_id
    AND is_vendor()
);


DROP POLICY IF EXISTS "Vendors delete their own reply" ON review_replies;
CREATE POLICY "Vendors delete their own reply" ON review_replies
FOR DELETE
USING (
    (
        auth.uid() = vendor_id
        AND is_vendor()
    )
    OR is_admin()
);


DROP POLICY IF EXISTS "Admins have full access to review replies" ON review_replies;
CREATE POLICY "Admins have full access to review replies" ON review_replies
FOR ALL
USING (
    is_admin()
)
WITH CHECK (
    is_admin()
);


-- =============================================================================
-- SECTION 14: PERFORMANCE INDEXES
-- =============================================================================

CREATE INDEX IF NOT EXISTS idx_reviews_food_item_id
    ON reviews(food_item_id)
    WHERE is_visible = true;


CREATE INDEX IF NOT EXISTS idx_reviews_student_id
    ON reviews(student_id);


CREATE INDEX IF NOT EXISTS idx_reviews_order_item_id
    ON reviews(order_item_id);


CREATE INDEX IF NOT EXISTS idx_reviews_order_id
    ON reviews(order_id);


CREATE INDEX IF NOT EXISTS idx_review_replies_review
    ON review_replies(review_id);


CREATE INDEX IF NOT EXISTS idx_review_replies_vendor
    ON review_replies(vendor_id);


-- =============================================================================
-- SECTION 15: RPC -- get_food_reviews
-- =============================================================================
--
-- Returns:
--   reviews
--   total
--
-- Correct pagination happens BEFORE json aggregation.
-- =============================================================================

CREATE OR REPLACE FUNCTION get_food_reviews(
    p_food_item_id UUID,
    p_limit        INTEGER DEFAULT 20,
    p_offset       INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_results JSONB;
    v_total   INTEGER;
BEGIN

    p_limit := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
    p_offset := GREATEST(COALESCE(p_offset, 0), 0);


    SELECT COUNT(*)
    INTO v_total
    FROM reviews
    WHERE food_item_id = p_food_item_id
      AND is_visible = true;


    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id',            r.id,
                'student_id',    r.student_id,
                'student_name',  p.name,
                'food_item_id',  r.food_item_id,
                'order_id',      r.order_id,
                'order_item_id', r.order_item_id,
                'rating',        r.rating,
                'review_text',   r.review_text,
                'is_visible',    r.is_visible,
                'created_at',    r.created_at,
                'updated_at',    r.updated_at,

                'vendor_reply',
                CASE
                    WHEN rr.id IS NOT NULL THEN
                        jsonb_build_object(
                            'id',         rr.id,
                            'vendor_id',  rr.vendor_id,
                            'reply_text', rr.reply_text,
                            'created_at', rr.created_at,
                            'updated_at', rr.updated_at
                        )
                    ELSE NULL
                END
            )
            ORDER BY r.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_results
    FROM (
        SELECT *
        FROM reviews
        WHERE food_item_id = p_food_item_id
          AND is_visible = true
        ORDER BY created_at DESC
        LIMIT p_limit
        OFFSET p_offset
    ) r
    JOIN profiles p
        ON p.id = r.student_id
    LEFT JOIN review_replies rr
        ON rr.review_id = r.id;


    RETURN jsonb_build_object(
        'reviews', v_results,
        'total', v_total
    );

END;
$$;


REVOKE ALL
ON FUNCTION get_food_reviews(UUID, INTEGER, INTEGER)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION get_food_reviews(UUID, INTEGER, INTEGER)
TO authenticated, anon;


-- =============================================================================
-- SECTION 16: RPC -- get_review_for_order_item
-- =============================================================================

CREATE OR REPLACE FUNCTION get_review_for_order_item(
    p_order_item_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_uid    UUID := auth.uid();
    v_review JSONB;
BEGIN

    IF v_uid IS NULL THEN
        RAISE EXCEPTION
            'Authentication required.';
    END IF;


    SELECT jsonb_build_object(
        'id',            r.id,
        'student_id',    r.student_id,
        'food_item_id',  r.food_item_id,
        'order_id',      r.order_id,
        'order_item_id', r.order_item_id,
        'rating',        r.rating,
        'review_text',   r.review_text,
        'is_visible',    r.is_visible,
        'created_at',    r.created_at,
        'updated_at',    r.updated_at
    )
    INTO v_review
    FROM reviews r
    WHERE r.order_item_id = p_order_item_id
      AND r.student_id = v_uid;


    RETURN v_review;

END;
$$;


REVOKE ALL
ON FUNCTION get_review_for_order_item(UUID)
FROM PUBLIC;

