ON FUNCTION get_review_for_order_item(UUID)
TO authenticated;


-- =============================================================================
-- SECTION 17: RPC -- get_vendor_reviews
-- =============================================================================
--
-- Returns reviews belonging to food items sold by the authenticated vendor.
-- Supports multiple outlets owned by the same vendor.
-- =============================================================================

CREATE OR REPLACE FUNCTION get_vendor_reviews(
    p_limit  INTEGER DEFAULT 50,
    p_offset INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_uid     UUID := auth.uid();
    v_role    TEXT := get_user_role();
    v_results JSONB;
    v_total   INTEGER;
BEGIN

    IF v_uid IS NULL OR v_role != 'VENDOR' THEN
        RAISE EXCEPTION
            'Only vendors can call this function.';
    END IF;


    p_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
    p_offset := GREATEST(COALESCE(p_offset, 0), 0);


    SELECT COUNT(*)
    INTO v_total
    FROM reviews r
    JOIN food_items fi
        ON fi.id = r.food_item_id
    JOIN outlets o
        ON o.id = fi.outlet_id
    WHERE o.vendor_id = v_uid;


    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id',            r.id,
                'student_id',    r.student_id,
                'student_name',  p.name,
                'food_item_id',  r.food_item_id,
                'food_name',     fi.name,
                'outlet_id',     o.id,
                'outlet_name',   o.name,
                'order_id',      r.order_id,
                'order_item_id', r.order_item_id,
                'rating',        r.rating,
                'review_text',   r.review_text,
                'is_visible',    r.is_visible,
                'created_at',    r.created_at,
                'updated_at',    r.updated_at,

                'vendor_reply',
                CASE
                    WHEN rr.id IS NOT NULL THEN
                        jsonb_build_object(
                            'id',         rr.id,
                            'reply_text', rr.reply_text,
                            'created_at', rr.created_at,
                            'updated_at', rr.updated_at
                        )
                    ELSE NULL
                END
            )
            ORDER BY r.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_results
    FROM (
        SELECT r.*
        FROM reviews r
        JOIN food_items fi
            ON fi.id = r.food_item_id
        JOIN outlets o
            ON o.id = fi.outlet_id
        WHERE o.vendor_id = v_uid
        ORDER BY r.created_at DESC
        LIMIT p_limit
        OFFSET p_offset
    ) r
    JOIN profiles p
        ON p.id = r.student_id
    JOIN food_items fi
        ON fi.id = r.food_item_id
    JOIN outlets o
        ON o.id = fi.outlet_id
    LEFT JOIN review_replies rr
        ON rr.review_id = r.id;


    RETURN jsonb_build_object(
        'reviews', v_results,
        'total', v_total
    );

END;
$$;


REVOKE ALL
ON FUNCTION get_vendor_reviews(INTEGER, INTEGER)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION get_vendor_reviews(INTEGER, INTEGER)
TO authenticated;


