CREATE POLICY "Students and vendors see visible outlet reviews" ON outlet_reviews
FOR SELECT
USING (
    is_visible = true
    OR is_admin()
);

DROP POLICY IF EXISTS "Students insert their own outlet reviews" ON outlet_reviews;
CREATE POLICY "Students insert their own outlet reviews" ON outlet_reviews
FOR INSERT
WITH CHECK (
    auth.uid() = student_id
    AND is_student()
);

DROP POLICY IF EXISTS "Students update their own outlet reviews" ON outlet_reviews;
CREATE POLICY "Students update their own outlet reviews" ON outlet_reviews
FOR UPDATE
USING (
    auth.uid() = student_id
    AND is_student()
)
WITH CHECK (
    auth.uid() = student_id
    AND is_student()
);

DROP POLICY IF EXISTS "Students delete their own outlet reviews" ON outlet_reviews;
CREATE POLICY "Students delete their own outlet reviews" ON outlet_reviews
FOR DELETE
USING (
    auth.uid() = student_id
    AND is_student()
);

DROP POLICY IF EXISTS "Admins have full access to outlet reviews" ON outlet_reviews;
CREATE POLICY "Admins have full access to outlet reviews" ON outlet_reviews
FOR ALL
USING (
    is_admin()
)
WITH CHECK (
    is_admin()
);


-- =============================================================================
-- SECTION 11: RLS POLICIES -- outlet_review_replies
-- =============================================================================

DROP POLICY IF EXISTS "Anyone can see outlet review replies" ON outlet_review_replies;
CREATE POLICY "Anyone can see outlet review replies" ON outlet_review_replies
FOR SELECT
USING (
    EXISTS (
        SELECT 1
        FROM outlet_reviews r
        WHERE r.id = outlet_review_replies.outlet_review_id
          AND (
              r.is_visible = true
              OR is_admin()
          )
    )
);

DROP POLICY IF EXISTS "Vendors insert their own outlet reply" ON outlet_review_replies;
CREATE POLICY "Vendors insert their own outlet reply" ON outlet_review_replies
FOR INSERT
WITH CHECK (
    auth.uid() = vendor_id
    AND is_vendor()
);

DROP POLICY IF EXISTS "Vendors update their own outlet reply" ON outlet_review_replies;
CREATE POLICY "Vendors update their own outlet reply" ON outlet_review_replies
FOR UPDATE
USING (
    auth.uid() = vendor_id
    AND is_vendor()
)
WITH CHECK (
    auth.uid() = vendor_id
    AND is_vendor()
);

DROP POLICY IF EXISTS "Vendors delete their own outlet reply" ON outlet_review_replies;
CREATE POLICY "Vendors delete their own outlet reply" ON outlet_review_replies
FOR DELETE
USING (
    (
        auth.uid() = vendor_id
        AND is_vendor()
    )
    OR is_admin()
);

DROP POLICY IF EXISTS "Admins have full access to outlet review replies" ON outlet_review_replies;
CREATE POLICY "Admins have full access to outlet review replies" ON outlet_review_replies
FOR ALL
USING (
    is_admin()
)
WITH CHECK (
    is_admin()
);


