-- =============================================================================
-- SECTION 13: RPC -- get_outlet_reviews
-- =============================================================================

CREATE OR REPLACE FUNCTION get_outlet_reviews(
    p_outlet_id UUID,
    p_limit INTEGER DEFAULT 20,
    p_offset INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_results JSONB;
    v_total   INTEGER;
BEGIN

    p_limit := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
    p_offset := GREATEST(COALESCE(p_offset, 0), 0);

    SELECT COUNT(*)
    INTO v_total
    FROM outlet_reviews
    WHERE outlet_id = p_outlet_id
      AND is_visible = true;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id',            r.id,
                'student_id',    r.student_id,
                'student_name',  p.name,
                'outlet_id',     r.outlet_id,
                'order_id',      r.order_id,
                'rating',        r.rating,
                'review_text',   r.review_text,
                'is_visible',    r.is_visible,
                'created_at',    r.created_at,
                'updated_at',    r.updated_at,

                'vendor_reply',
                CASE
                    WHEN rr.id IS NOT NULL THEN
                        jsonb_build_object(
                            'id',         rr.id,
                            'vendor_id',  rr.vendor_id,
                            'reply_text', rr.reply_text,
                            'created_at', rr.created_at,
                            'updated_at', rr.updated_at
                        )
                    ELSE NULL
                END
            )
            ORDER BY r.created_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_results
    FROM (
        SELECT *
        FROM outlet_reviews
        WHERE outlet_id = p_outlet_id
          AND is_visible = true
        ORDER BY created_at DESC
        LIMIT p_limit
        OFFSET p_offset
    ) r
    JOIN profiles p
        ON p.id = r.student_id
    LEFT JOIN outlet_review_replies rr
        ON rr.outlet_review_id = r.id;

    RETURN jsonb_build_object(
        'reviews', v_results,
        'total', v_total
    );

END;
$$;

REVOKE ALL
ON FUNCTION get_outlet_reviews(UUID, INTEGER, INTEGER)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION get_outlet_reviews(UUID, INTEGER, INTEGER)
TO authenticated, anon;


-- =============================================================================
-- SECTION 14: RPC -- get_outlet_review_for_order
-- =============================================================================

CREATE OR REPLACE FUNCTION get_outlet_review_for_order(
    p_order_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_uid    UUID := auth.uid();
    v_review JSONB;
BEGIN

    IF v_uid IS NULL THEN
        RAISE EXCEPTION
            'Authentication required.';
    END IF;

    SELECT jsonb_build_object(
        'id',            r.id,
        'student_id',    r.student_id,
        'outlet_id',     r.outlet_id,
        'order_id',      r.order_id,
        'rating',        r.rating,
        'review_text',   r.review_text,
        'is_visible',    r.is_visible,
        'created_at',    r.created_at,
        'updated_at',    r.updated_at
    )
    INTO v_review
    FROM outlet_reviews r
    WHERE r.order_id = p_order_id
      AND r.student_id = v_uid;

    RETURN v_review;

END;
$$;

REVOKE ALL
ON FUNCTION get_outlet_review_for_order(UUID)
FROM PUBLIC;

GRANT EXECUTE
ON FUNCTION get_outlet_review_for_order(UUID)
TO authenticated;


